components/themevale/homepage/component/:
{{#each categories}}
    {{#if id '==' ../category_id}}
        <div class="themevale_productsByCategoryId layout-2">
            <div class="themevale_page-heading-wrapper">
                <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
                <a class="themevale_link" href="{{url}}">View More</a>
            </div>
            <div class="page-content" data-themevale-products-by-category="{{url}}">
                {{> components/themevale/homepage/component/product-loading theme_settings=../../theme_settings}}
            </div>
        </div>
    {{else}}
        {{#each children}}
            {{#if id '==' ../../../category_id}}
                <div class="themevale_productsByCategoryId layout-2">
                    <div class="themevale_page-heading-wrapper">
                        <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
                        <a class="themevale_link" href="{{url}}">View More</a>
                    </div>
                    <div class="page-content" data-themevale-products-by-category="{{url}}">
                        {{> components/themevale/homepage/component/product-loading theme_settings=../../../../theme_settings}}
                    </div>
                </div>
            {{else}}
                {{#each children}}
                    {{#if id '==' ../../../../../category_id}}
                        <div class="themevale_productsByCategoryId layout-2">
                            <div class="themevale_page-heading-wrapper">
                                <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
                                <a class="themevale_link" href="{{url}}">View More</a>
                            </div>
                            <div class="page-content" data-themevale-products-by-category="{{url}}">
                                {{> components/themevale/homepage/component/product-loading theme_settings=../../../../../../theme_settings}}
                            </div>
                        </div>
                    {{/if}}
                {{/each}}
            {{/if}}
        {{/each}}
    {{/if}}
{{/each}}
